const normalize = (value: string) =>
  value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[’']/g, "")
    .replace(/[^a-z0-9]/gi, "")
    .toLowerCase();

export function playerFaceUrl(name: string): string | undefined {
  const raw = RAW[normalize(name)];
  return raw?.startsWith("w:") ? `https://upload.wikimedia.org/wikipedia/${raw.slice(2)}` : raw;
}
